# Generated by the Niobium FHE Application Design AI Assistant (FHEanna).
#
# The patient's side: an interactive prompt.
#
# Generates this patient's keys once and uploads only the context, public and
# evaluation keys. Then, for each question: asks for the measurements,
# encrypts them locally, sends the ciphertext to the risk service, and
# decrypts the reply. The secret key and the plain measurements never leave
# this machine. Press Enter at a prompt to keep the previous answer, so a
# "what if I quit smoking?" is one changed field.
#
# Usage: python3 risk_client.py [--server http://127.0.0.1:8765] [--home DIR]

import argparse
import os
import subprocess
import sys
import tempfile
import time
import urllib.request

HERE = os.path.dirname(os.path.abspath(__file__))
APP = os.path.dirname(HERE)
REPO = os.path.dirname(os.path.dirname(APP))
BUILD = os.path.join(REPO, "build", "examples")
sys.path.insert(0, os.path.join(APP, "design"))
import reference  # noqa: E402  (bounds, and the clear-text cross-check)


def http(method, url, data):
    req = urllib.request.Request(url, data=data, method=method)
    with urllib.request.urlopen(req) as r:
        return r.read()


def ask(prompt, prev, parse):
    while True:
        if prev is None:
            shown = ""
        elif parse is yes_no:
            shown = f" [{'y' if prev else 'n'}]"
        else:
            shown = f" [{prev:g}]" if isinstance(prev, float) else f" [{prev}]"
        s = input(f"  {prompt}{shown}: ").strip()
        if not s and prev is not None:
            return prev
        try:
            return parse(s)
        except ValueError as e:
            print(f"    {e}")


def in_range(name, lo, hi):
    def parse(s):
        v = float(s)
        if not lo <= v <= hi:
            raise ValueError(f"{name} must be between {lo:g} and {hi:g} (the range the model covers)")
        return v
    return parse


def yes_no(s):
    s = s.lower()
    if s in ("y", "yes", "1"):
        return 1
    if s in ("n", "no", "0"):
        return 0
    raise ValueError("answer y or n")


def sex(s):
    s = s.lower()[:1]
    if s not in ("m", "f"):
        raise ValueError("answer m or f")
    return s


def band(r):
    p = r * 100
    return "low" if p < 10 else ("intermediate" if p < 20 else "high")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--server", default="http://127.0.0.1:8765")
    ap.add_argument("--home", default=os.path.join(APP, "run_demo", "client_home"))
    a = ap.parse_args()
    os.makedirs(a.home, exist_ok=True)

    print("=== Private heart-disease risk check (Framingham 2008, office-based) ===")
    print("Your measurements are encrypted on this machine; the risk service only sees ciphertext.\n")
    print("Generating your keys...")
    subprocess.run([os.path.join(BUILD, "health_risk_keygen"), a.home], check=True,
                   stdout=subprocess.DEVNULL)
    for name in ("cc.bin", "pk.bin", "mk.bin", "rk.bin"):  # never sk.bin
        with open(os.path.join(a.home, name), "rb") as f:
            data = f.read()
        http("PUT", f"{a.server}/setup/{name}", data)
        print(f"  sent {name} ({len(data) / 1e6:.1f} MB) to the risk service")

    v = dict.fromkeys(["sex", "age", "bmi", "sbp", "treated", "smoker", "diabetic"])
    B = reference.BOUNDS
    while True:
        print()
        v["sex"] = ask("Sex (m/f)", v["sex"], sex)
        v["age"] = ask("Age in years", v["age"], in_range("age", *B["age"]))
        v["bmi"] = ask("Body-mass index (BMI)", v["bmi"], in_range("BMI", *B["bmi"]))
        v["sbp"] = ask("Systolic blood pressure (mmHg)", v["sbp"], in_range("blood pressure", *B["sbp"]))
        v["treated"] = ask("Taking blood-pressure medication? (y/n)", v["treated"], yes_no)
        v["smoker"] = ask("Smoker? (y/n)", v["smoker"], yes_no)
        v["diabetic"] = ask("Diabetic? (y/n)", v["diabetic"], yes_no)

        with tempfile.TemporaryDirectory() as td:
            ct_in, ct_out = os.path.join(td, "ct_x.bin"), os.path.join(td, "ct_result.bin")
            args = [v["sex"], v["age"], v["bmi"], v["sbp"], v["treated"], v["smoker"], v["diabetic"]]
            CMD=[os.path.join(BUILD, "health_risk_encrypt"), a.home, ct_in] + [str(x) for x in args]
            print("Running:", " ".join(CMD))
            enc = subprocess.run([os.path.join(BUILD, "health_risk_encrypt"), a.home, ct_in]
                                 + [str(x) for x in args], capture_output=True, text=True)
            if enc.returncode != 0:  # the encrypt step enforces the same bounds
                print(f"  {enc.stderr.strip()}")
                continue
            with open(ct_in, "rb") as f:
                data = f.read()
            print(f"  encrypted -> sending {len(data) / 1e6:.1f} MB ... ", end="", flush=True)
            t0 = time.monotonic()
            reply = http("POST", f"{a.server}/score", data)
            print(f"got {len(reply) / 1e6:.1f} MB back in {time.monotonic() - t0:.1f}s")
            with open(ct_out, "wb") as f:
                f.write(reply)
            dec = subprocess.run([os.path.join(BUILD, "health_risk_decrypt"), a.home, ct_out],
                                 capture_output=True, text=True, check=True)
        r = float(dec.stdout.split()[1])
        local = reference.risk("male" if v["sex"] == "m" else "female", *args[1:])
        print(f"\n  Your 10-year cardiovascular risk: {r * 100:.2f}%  ({band(r)})")
        print(f"  (cross-check computed in the clear on this machine: {local * 100:.2f}%)")
        if input("\nAnother question? [Y/n] ").strip().lower().startswith("n"):
            break


if __name__ == "__main__":
    try:
        main()
    except (KeyboardInterrupt, EOFError):
        print()
